120	    pub fn summary(&self, project_dir: Option<&str>, days: Option<i64>) -> Result<CostSummary> {
121	        let cutoff_ms = cutoff_ms(days);
122	        let map_row = |row: &rusqlite::Row| -> rusqlite::Result<CostSummary> {
123	            Ok(CostSummary {
124	                total_cost_usd: row.get(0)?,
125	                total_input_tokens: row.get::<_, i64>(1)? as u64,
126	                total_output_tokens: row.get::<_, i64>(2)? as u64,
127	                record_count: row.get::<_, i64>(3)? as u64,
128	            })
129	        };
130	        let row = if let Some(proj) = project_dir {
131	            self.conn.query_row(
132	                "SELECT COALESCE(SUM(cost_usd),0), COALESCE(SUM(input_tokens),0),
133	                 COALESCE(SUM(output_tokens),0), COUNT(*)
134	                 FROM cost_records WHERE timestamp_ms >= ?1 AND project_dir = ?2",
135	                params![cutoff_ms, proj],
136	                map_row,
137	            )?
138	        } else {
139	            self.conn.query_row(
140	                "SELECT COALESCE(SUM(cost_usd),0), COALESCE(SUM(input_tokens),0),
141	                 COALESCE(SUM(output_tokens),0), COUNT(*)
142	                 FROM cost_records WHERE timestamp_ms >= ?1",
143	                params![cutoff_ms],
144	                map_row,
145	            )?
146	        };
147	        Ok(row)
148	    }
