150	    pub fn by_group(&self, group_col: &str, project_dir: Option<&str>, days: Option<i64>) -> Result<Vec<CostBreakdown>> {
151	        self.by_group_limit(group_col, project_dir, days, 100)
152	    }
153	
154	    pub fn by_group_limit(&self, group_col: &str, project_dir: Option<&str>, days: Option<i64>, limit: u32) -> Result<Vec<CostBreakdown>> {
155	        let col = match group_col {
156	            "pr" => "pr_ref",
157	            "dev" | "developer" => "developer_id",
158	            "model" => "model_id",
159	            "day" => "date(timestamp_ms/1000, 'unixepoch')",
160	            "session" => "session_id",
161	            _ => return Err(anyhow::anyhow!("unknown group: {}", group_col)),
162	        };
163	
164	        let cutoff_ms = cutoff_ms(days);
165	        let sql = if project_dir.is_some() {
166	            format!(
167	                "SELECT {col} as grp, SUM(cost_usd), SUM(input_tokens), SUM(output_tokens), COUNT(*)
168	                 FROM cost_records WHERE timestamp_ms >= ?1 AND project_dir = ?2
169	                 GROUP BY grp ORDER BY SUM(cost_usd) DESC LIMIT {limit}"
170	            )
171	        } else {
172	            format!(
173	                "SELECT {col} as grp, SUM(cost_usd), SUM(input_tokens), SUM(output_tokens), COUNT(*)
174	                 FROM cost_records WHERE timestamp_ms >= ?1 AND (?2 = '' OR project_dir = ?2)
175	                 GROUP BY grp ORDER BY SUM(cost_usd) DESC LIMIT {limit}"
176	            )
177	        };
178	
179	        let proj = project_dir.unwrap_or("").to_string();
180	        let mut stmt = self.conn.prepare(&sql)?;
181	        let rows = stmt.query_map(params![cutoff_ms, proj], |row| {
182	            Ok(CostBreakdown {
183	                key: row.get::<_, String>(0).unwrap_or_default(),
184	                cost_usd: row.get(1)?,
185	                input_tokens: row.get::<_, i64>(2)? as u64,
186	                output_tokens: row.get::<_, i64>(3)? as u64,
187	                record_count: row.get::<_, i64>(4)? as u64,
188	            })
189	        })?;
190	        let mut result = Vec::new();
191	        for r in rows {
192	            result.push(r?);
193	        }
194	        Ok(result)
195	    }
196	
197	    pub fn accumulated_cost(&self, project_dir: &str, days: Option<i64>) -> Result<f64> {
198	        let cutoff_ms = cutoff_ms(days);
199	        let cost: f64 = self.conn.query_row(
200	            "SELECT COALESCE(SUM(cost_usd), 0) FROM cost_records
201	             WHERE timestamp_ms >= ?1 AND project_dir = ?2",
202	            params![cutoff_ms, project_dir],
203	            |row| row.get(0),
204	        )?;
205	        Ok(cost)
206	    }
