208	    pub fn accumulated_cost_by_dev(&self, developer_id: &str, days: Option<i64>) -> Result<f64> {
209	        let cutoff_ms = cutoff_ms(days);
210	        let cost: f64 = self.conn.query_row(
211	            "SELECT COALESCE(SUM(cost_usd), 0) FROM cost_records
212	             WHERE timestamp_ms >= ?1 AND developer_id = ?2",
213	            params![cutoff_ms, developer_id],
214	            |row| row.get(0),
215	        )?;
216	        Ok(cost)
217	    }
218	
219	    pub fn by_pr(&self, pr_ref: &str, days: Option<i64>) -> Result<Vec<CostBreakdown>> {
220	        let cutoff_ms = cutoff_ms(days);
221	        let mut stmt = self.conn.prepare(
222	            "SELECT model_id as grp, SUM(cost_usd), SUM(input_tokens), SUM(output_tokens), COUNT(*)
223	             FROM cost_records WHERE timestamp_ms >= ?1 AND pr_ref = ?2
224	             GROUP BY grp ORDER BY SUM(cost_usd) DESC",
225	        )?;
226	        let rows = stmt.query_map(params![cutoff_ms, pr_ref], |row| {
227	            Ok(CostBreakdown {
228	                key: row.get::<_, String>(0).unwrap_or_default(),
229	                cost_usd: row.get(1)?,
230	                input_tokens: row.get::<_, i64>(2)? as u64,
231	                output_tokens: row.get::<_, i64>(3)? as u64,
232	                record_count: row.get::<_, i64>(4)? as u64,
233	            })
234	        })?;
235	        let mut result = Vec::new();
236	        for r in rows {
237	            result.push(r?);
238	        }
239	        Ok(result)
240	    }
241	
242	    pub fn record_count(&self) -> Result<u64> {
243	        let count: i64 = self.conn.query_row(
244	            "SELECT COUNT(*) FROM cost_records",
245	            [],
246	            |row| row.get(0),
247	        )?;
248	        Ok(count as u64)
249	    }
250	
251	    pub fn cleanup(&self, retention_days: i64) -> Result<u64> {
252	        let cutoff_ms = cutoff_ms(Some(retention_days));
253	        let changes = self.conn.execute(
254	            "DELETE FROM cost_records WHERE timestamp_ms < ?1",
255	            params![cutoff_ms],
256	        )?;
257	        Ok(changes as u64)
258	    }
259	}
260	
261	fn cutoff_ms(days: Option<i64>) -> i64 {
262	    let days = days.unwrap_or(90);
263	    let now_ms = chrono::Utc::now().timestamp_millis();
264	    now_ms - (days * 86_400_000)
265	}
