66	impl TrackingDb {
67	    pub fn open(db_path: &Path) -> Result<Self> {
68	        let conn = Connection::open(db_path)?;
69	        conn.execute_batch(
70	            "PRAGMA journal_mode=WAL;
71	             PRAGMA synchronous=NORMAL;
72	             PRAGMA busy_timeout=5000;"
73	        )?;
74	        conn.execute_batch(
75	            "CREATE TABLE IF NOT EXISTS tracking_events (
76	                id INTEGER PRIMARY KEY AUTOINCREMENT,
77	                timestamp INTEGER NOT NULL,
78	                command TEXT NOT NULL,
79	                input_tokens INTEGER NOT NULL,
80	                output_tokens INTEGER NOT NULL,
81	                tokens_saved INTEGER NOT NULL,
82	                layer TEXT NOT NULL,
83	                project TEXT NOT NULL,
84	                session_id TEXT NOT NULL
85	            );"
86	        )?;
87	        conn.execute_batch(
88	            "CREATE INDEX IF NOT EXISTS idx_tracking_timestamp
89	             ON tracking_events(timestamp);"
90	        )?;
91	        Ok(Self { conn })
92	    }
93	
94	    pub fn record(&self, event: &TrackingEvent) -> Result<()> {
95	        let now = now_secs();
96	        self.conn.execute(
97	            "INSERT INTO tracking_events
98	             (timestamp, command, input_tokens, output_tokens, tokens_saved,
99	              layer, project, session_id)
100	             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)",
101	            params![
102	                now as i64,
103	                event.command,
104	                event.input_tokens as i64,
105	                event.output_tokens as i64,
106	                event.tokens_saved as i64,
107	                event.layer.as_str(),
108	                event.project,
109	                event.session_id,
110	            ],
111	        )?;
112	        Ok(())
113	    }
