68	    pub fn cost_for_tokens(
69	        &self,
70	        model_id: &str,
71	        input_tokens: u64,
72	        output_tokens: u64,
73	        cache_read_tokens: u64,
74	        cache_write_tokens: u64,
75	    ) -> f64 {
76	        let pricing = self.resolve(model_id);
77	        let input_cost = input_tokens as f64 * pricing.input_per_mtok / 1_000_000.0;
78	        let output_cost = output_tokens as f64 * pricing.output_per_mtok / 1_000_000.0;
79	        let cache_r = cache_read_tokens as f64 * pricing.cache_read_per_mtok / 1_000_000.0;
80	        let cache_w = cache_write_tokens as f64 * pricing.cache_write_per_mtok / 1_000_000.0;
81	        input_cost + output_cost + cache_r + cache_w
82	    }
83	
84	    pub fn resolve(&self, model_id: &str) -> &ModelPricing {
85	        if let Some(p) = self.models.get(model_id) {
86	            return p;
87	        }
88	        let normalized = normalize_model_id(model_id);
89	        if let Some(p) = self.models.get(&normalized) {
90	            return p;
91	        }
92	        let mut keys: Vec<&String> = self.models.keys().collect();
93	        keys.sort_by(|a, b| b.len().cmp(&a.len()));
94	        for key in keys {
95	            if model_id.starts_with(key.as_str()) || normalized.starts_with(key.as_str()) {
96	                return &self.models[key];
97	            }
98	        }
99	        tracing::warn!("unknown model '{}', using median pricing", model_id);
100	        self.median_pricing()
101	    }
102	
103	    fn median_pricing(&self) -> &ModelPricing {
104	        static MEDIAN: ModelPricing = ModelPricing {
105	            input_per_mtok: 3.0,
106	            output_per_mtok: 15.0,
107	            cache_read_per_mtok: 0.375,
108	            cache_write_per_mtok: 3.75,
109	        };
110	        &MEDIAN
111	    }
112	}
113	
114	fn normalize_model_id(id: &str) -> String {
115	    let id = id.trim();
116	    let id = id.split(':').last().unwrap_or(id);
117	    let parts: Vec<&str> = id.rsplitn(2, '-').collect();
118	    if parts.len() == 2 && parts[0].len() == 8 && parts[0].chars().all(|c| c.is_ascii_digit()) {
119	        parts[1].to_string()
120	    } else {
121	        id.to_string()
122	    }
123	}
