140	    pub fn evaluate(
141	        &self,
142	        developer_id: &str,
143	        project_dir: &str,
144	        accumulated_dev: f64,
145	        accumulated_project: f64,
146	    ) -> Verdict {
147	        let mut worst_pct: u32 = 0;
148	        let mut worst_msg: Option<String> = None;
149	
150	        for rule in &self.config.limits {
151	            let (accumulated, scope_label) = match rule.scope.as_str() {
152	                "developer" => {
153	                    if rule.id != "*" && rule.id != developer_id {
154	                        continue;
155	                    }
156	                    (accumulated_dev, format!("developer:{}", developer_id))
157	                }
158	                "project" => {
159	                    let proj_name = project_dir
160	                        .rsplit(['/', '\\'])
161	                        .find(|s| !s.is_empty())
162	                        .unwrap_or(project_dir);
163	                    if rule.id != "*" && rule.id != proj_name {
164	                        continue;
165	                    }
166	                    (accumulated_project, format!("project:{}", proj_name))
167	                }
168	                _ => continue,
169	            };
170	
171	            let pct = if rule.max_usd > 0.0 {
172	                (accumulated.max(0.0) / rule.max_usd * 100.0).ceil() as u32
173	            } else {
174	                100
175	            };
176	
177	            let block_pct = self.config.global.block_at_pct;
178	            let warn_pct = self.config.global.warn_at_pct;
179	
180	            if pct >= block_pct && rule.action_on_exceed == "block" {
181	                return Verdict::Block(format!(
182	                    "Budget exceeded for {} — ${:.2}/${:.2} ({}%)",
183	                    scope_label, accumulated, rule.max_usd, pct
184	                ));
185	            }
186	
187	            if pct >= warn_pct && pct > worst_pct {
188	                worst_pct = pct;
189	                worst_msg = Some(format!(
190	                    "Budget warning for {} — ${:.2}/${:.2} ({}%)",
191	                    scope_label, accumulated, rule.max_usd, pct
192	                ));
193	            }
194	        }
195	
196	        match worst_msg {
197	            Some(msg) => Verdict::Warn(msg),
198	            None => Verdict::Allow,
199	        }
200	    }
201	
202	    pub fn config(&self) -> &PolicyConfig {
203	        &self.config
204	    }
205	}
