147	pub fn record_manual(
148	    session_id: &str,
149	    model_id: &str,
150	    input_tokens: u64,
151	    output_tokens: u64,
152	    cost_override: Option<f64>,
153	) -> Result<()> {
154	    let db_path = paths::data_dir().join("cost.db");
155	    std::fs::create_dir_all(paths::data_dir())?;
156	    let store = CostStore::open(&db_path)?;
157	
158	    let pricing = codeflow_core::pricing::PricingTable::bundled();
159	    let cost = cost_override.unwrap_or_else(|| {
160	        pricing.cost_for_tokens(model_id, input_tokens, output_tokens, 0, 0)
161	    });
162	
163	    let pr_ref = codeflow_core::pr_linker::detect_pr_ref().unwrap_or_default();
164	    let feature_tag = codeflow_core::pr_linker::detect_feature_tag().unwrap_or_default();
165	    let project_dir = std::env::current_dir()
166	        .unwrap_or_default()
167	        .to_string_lossy()
168	        .to_string();
169	
170	    let rec = codeflow_core::cost::CostRecord {
171	        id: None,
172	        session_id: session_id.to_string(),
173	        timestamp_ms: chrono::Utc::now().timestamp_millis(),
174	        model_id: model_id.to_string(),
175	        input_tokens,
176	        output_tokens,
177	        cache_read_tokens: 0,
178	        cache_write_tokens: 0,
179	        cost_usd: cost,
180	        pr_ref,
181	        feature_tag,
182	        project_dir,
183	        developer_id: codeflow_core::util::developer_id(),
184	    };
185	
186	    let id = store.record(&rec)?;
187	    println!(
188	        "✓ Cost recorded: ${:.4} ({} → {}) [id={}]",
189	        cost, model_id, format_number(input_tokens + output_tokens), id
190	    );
191	
192	    Ok(())
193	}
