195	fn format_number(n: u64) -> String {
196	    if n >= 1_000_000 {
197	        format!("{:.1}M", n as f64 / 1_000_000.0)
198	    } else if n >= 1_000 {
199	        format!("{:.1}K", n as f64 / 1_000.0)
200	    } else {
201	        n.to_string()
202	    }
203	}
