205	fn truncate(s: &str, max: usize) -> String {
206	    if s.chars().count() > max {
207	        let truncated: String = s.chars().take(max - 1).collect();
208	        format!("{}…", truncated)
209	    } else {
210	        s.to_string()
211	    }
212	}
