5	// Versioning contract: proto3 additive-only.
6	// Never remove or rename fields. Ingest accepts v1+ with defaults.
7	
8	message EventBatch {
9	  string cli_version = 1;
10	  string machine_id = 2;
11	  repeated Event events = 3;
12	}
13	
14	message Event {
15	  string id = 1;
16	  int64 timestamp_ms = 2;
17	  string session_id = 3;
18	  string project_dir = 4;
19	  string command = 5;
20	  EventType event_type = 6;
21	  CompressionEvent compression = 7;
22	  DedupEvent dedup = 8;
23	  ProvenanceEvent provenance = 9;
24	  CostEvent cost = 10;
25	  GovernanceEvent governance = 11;
26	  QualityEvent quality = 12;
27	}
28	
29	enum EventType {
30	  EVENT_TYPE_UNSPECIFIED = 0;
31	  EVENT_TYPE_COMPRESSION = 1;
32	  EVENT_TYPE_DEDUP = 2;
33	  EVENT_TYPE_PROVENANCE = 3;
34	  EVENT_TYPE_COST = 4;
35	  EVENT_TYPE_GOVERNANCE = 5;
36	  EVENT_TYPE_QUALITY = 6;
37	}
38	
39	message CompressionEvent {
40	  uint64 input_bytes = 1;
41	  uint64 output_bytes = 2;
42	  uint64 input_tokens = 3;
43	  uint64 output_tokens = 4;
44	  uint64 tokens_saved = 5;
45	  string filter_name = 6;
46	  string compression_level = 7;
47	  double latency_ms = 8;
48	}
49	
50	message DedupEvent {
51	  string content_hash = 1;
52	  bool cache_hit = 2;
53	  uint64 tokens_saved = 3;
54	  string file_path = 4;
55	  double latency_ms = 5;
56	}
57	
58	enum ContributorType {
59	  CONTRIBUTOR_TYPE_UNKNOWN = 0;
60	  CONTRIBUTOR_TYPE_HUMAN = 1;
61	  CONTRIBUTOR_TYPE_AI = 2;
62	  CONTRIBUTOR_TYPE_MIXED = 3;
63	}
64	
65	message ProvenanceEvent {
66	  string file_path = 1;
67	  string code_hash = 2;
68	  string model_id = 3;
69	  string model_version = 4;
70	  ContributorType contributor_type = 5;
71	  uint32 start_line = 6;
72	  uint32 end_line = 7;
