12	)
13	
14	func init() {
15		if key := os.Getenv("STRIPE_SECRET_KEY"); key != "" {
16			stripe.Key = key
17		}
18	}
19	
20	func (h *handler) handleBillingStatus(w http.ResponseWriter, r *http.Request) {
21		tenantID := tenantFromCtx(r)
22	
23		status, err := h.store.GetBillingStatus(r.Context(), tenantID)
24		if err != nil {
25			h.logger.Error("billing status query failed", "error", err)
26		}
27	
28		w.Header().Set("Content-Type", "application/json")
29		json.NewEncoder(w).Encode(status)
30	}
31	
32	func (h *handler) handleCreateCheckout(w http.ResponseWriter, r *http.Request) {
33		tenantID := tenantFromCtx(r)
34	
35		priceID := os.Getenv("STRIPE_PRO_PRICE_ID")
36		if priceID == "" {
37			http.Error(w, "billing not configured", http.StatusServiceUnavailable)
38			return
39		}
40	
41		successURL := os.Getenv("DASHBOARD_URL")
42		if successURL == "" {
43			successURL = "http://localhost:3000"
44		}
45	
46		params := &stripe.CheckoutSessionParams{
47			Mode: stripe.String(string(stripe.CheckoutSessionModeSubscription)),
48			LineItems: []*stripe.CheckoutSessionLineItemParams{
49				{
50					Price:    stripe.String(priceID),
51					Quantity: stripe.Int64(1),
52				},
53			},
54			SuccessURL: stripe.String(successURL + "/billing?status=success"),
55			CancelURL:  stripe.String(successURL + "/billing?status=cancelled"),
56			ClientReferenceID: stripe.String(tenantID),
57			Metadata: map[string]string{
58				"tenant_id": tenantID,
59			},
60		}
61	
62		s, err := session.New(params)
63		if err != nil {
64			h.logger.Error("stripe checkout creation failed", "error", err)
65			http.Error(w, "checkout failed", http.StatusInternalServerError)
66			return
67		}
68	
69		w.Header().Set("Content-Type", "application/json")
70		json.NewEncoder(w).Encode(map[string]string{
71			"checkout_url": s.URL,
72		})
73	}
74	
75	func (h *handler) handleStripeWebhook(w http.ResponseWriter, r *http.Request) {
76		body, err := io.ReadAll(io.LimitReader(r.Body, 65536))
77		if err != nil {
78			http.Error(w, "read error", http.StatusBadRequest)
79			return
80		}
81	
82		endpointSecret := os.Getenv("STRIPE_WEBHOOK_SECRET")
83		if endpointSecret == "" {
84			h.logger.Warn("stripe webhook secret not configured")
85			http.Error(w, "webhook not configured", http.StatusServiceUnavailable)
86			return
87		}
88	
89		event, err := webhook.ConstructEvent(body, r.Header.Get("Stripe-Signature"), endpointSecret)
90		if err != nil {
91			h.logger.Error("stripe webhook signature verification failed", "error", err)
92			http.Error(w, "invalid signature", http.StatusBadRequest)
93			return
94		}
95	
96		switch event.Type {
97		case "checkout.session.completed":
98			var cs stripe.CheckoutSession
99			if err := json.Unmarshal(event.Data.Raw, &cs); err != nil {
100				h.logger.Error("unmarshal checkout session", "error", err)
101				break
102			}
103			tenantID := cs.Metadata["tenant_id"]
104			if tenantID == "" {
105				tenantID = cs.ClientReferenceID
106			}
107			if tenantID != "" {
108				h.logger.Info("subscription activated", "tenant", tenantID)
109				if err := h.store.SetBillingStatus(r.Context(), tenantID, "pro", "active"); err != nil {
110					h.logger.Error("set billing status failed", "error", err)
111				}
112			}
113	
114		case "customer.subscription.deleted":
115			var sub stripe.Subscription
116			if err := json.Unmarshal(event.Data.Raw, &sub); err != nil {
117				break
118			}
119			tenantID := sub.Metadata["tenant_id"]
120			if tenantID != "" {
121				h.logger.Info("subscription cancelled", "tenant", tenantID)
122				if err := h.store.SetBillingStatus(r.Context(), tenantID, "free", "cancelled"); err != nil {
123					h.logger.Error("set billing status failed", "error", err)
124				}
125			}
126		}
127	
128		w.WriteHeader(http.StatusOK)
129	}
